"""Categorized Persian diagnostics, costs, pyramids, cohorts and individual evidence."""
from pathlib import Path
import json,html
ROOT=Path(__file__).resolve().parents[1];OUT=ROOT/'high_cagr/output'
def f(x):return '—' if x is None else f'{x:,.2f}'
def table(headers,rows):
 return '<div class="scroll"><table><thead><tr>'+''.join('<th>'+html.escape(str(h))+'</th>' for h in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+str(c)+'</td>' for c in r)+'</tr>' for r in rows)+'</tbody></table></div>'
def main():
 d=json.loads((OUT/'failure_diagnostics.json').read_text());r=d['periods']['full'];labels=d['rules'];losers=r['negative_positions'];costs=r['fees']-r['funding_pnl']+r['slippage_drag'];before=r['net_pnl']+costs
 categories=table(['دستهٔ انحصاری','تعداد','سهم از باخت‌ها ٪','جمع زیان خالص $','میانگین باخت $','میانهٔ مدت (ساعت)'],[[labels[k],v['positions'],f(v['share_of_losing_positions_pct']),f(v['negative_pnl']),f(v['avg_loss']),f(v['median_hours'])] for k,v in sorted(r['category_totals'].items(),key=lambda x:x[1]['positions'],reverse=True)])
 periods=table(['دورهٔ مستقل','پوزیشن','باخت','Win Rate ٪','میانگین برد $','میانگین باخت $','سود خالص $'],[[name,v['positions'],v['negative_positions'],f(v['win_rate_pct']),f(v['avg_win']),f(v['avg_loss']),f(v['net_pnl'])] for key,name in [('full','کل پنج سال'),('train','Train ۲۰۲۱–۲۰۲۴'),('oos','اعتبارسنجی ۲۰۲۵–۲۰۲۶')] for v in [d['periods'][key]]])
 def cohort(key,title):
  return '<h3>'+title+'</h3>'+table(['گروه','پوزیشن','باخت','Win Rate ٪','سود خالص $','کارمزد $'],[[html.escape(k),v['positions'],v['losses'],f(v['win_rate_pct']),f(v['net_pnl']),f(v['fees'])] for k,v in r['cohorts'][key].items()])
 cohorts=cohort('symbol','نمادها')+cohort('side','Long / Short')+cohort('exit_year','سال خروج (۲۰۲۱ و ۲۰۲۶ ناقص‌اند)')+cohort('exit_kind','نوع استاپ خروج')
 filters=cohort('adx_cohort','ADX چهار‌ساعته هنگام ورود')+cohort('breakout_cohort','فاصلهٔ شکست از مرز سخت‌تر Donchian/Kumo')+cohort('slope_cohort','شیب کیجون در جهت معامله نسبت به سه کندل قبل')
 worst=table(['ID پایه','نماد','جهت','ورود UTC','خروج UTC','زیان خالص $','MFE / R','MAE / R','دسته','ADX ورود'],[[x['position_id'],x['symbol'],x['side'],x['entry_utc'],x['exit_utc'],f(x['net_pnl']),f(x['mfe_r']),f(x['mae_r']),labels[x['category']],f(x['entry_adx14'])] for x in r['worst_positions']])
 clusters=table(['بازهٔ خروج ۴H — UTC','تعداد','باخت','نمادها','سود/زیان خالص $'],[[x['utc'],x['positions'],x['losses'],x['symbols'],f(x['net_pnl'])] for x in r['worst_exit_clusters'][:10]])
 streaks=table(['تعداد باخت متوالی در ترتیب خروج','شروع UTC','آخرین خروج UTC'],[[x['length'],x['start_utc'],x['end_utc']] for x in r['largest_streaks'][:5]])
 dd=r['drawdown_window'];pyr=r['pyramid'];largest=max(r['category_totals'].items(),key=lambda x:x[1]['positions']);cost_flip=r['category_totals'].get('COST_FLIP',{'positions':0});matched=json.loads((OUT/'matrix.json').read_text());w=matched['winner'];base=next(x for x in matched['matrix'] if not x['pyramid'] and all(x[k]==w[k] for k in ['universe','preset','entry_timeframe','lookback','trail','risk','max_open_positions']))
 s=f'''<!doctype html><html lang="fa" dir="rtl"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>عارضه‌یابی معاملات زیان‌ده Donchian</title><style>body{{font:14px/1.9 Tahoma,Arial;background:#101827;color:#edf4fc;margin:0;padding:24px}}section{{background:#1c2a40;padding:22px;border-radius:12px;margin:18px 0}}h1,h2,h3{{color:#79d9cc}}table{{border-collapse:collapse;width:100%;font-size:12px}}td,th{{border:1px solid #3b4b63;padding:10px}}td{{direction:ltr}}th{{background:#293b53}}.scroll{{overflow:auto}}.note{{border-right:4px solid #e1b567;padding-right:14px}}a{{color:#82d8ff}}@media(max-width:650px){{body{{padding:8px}}section{{padding:12px}}}}</style><h1>عارضه‌یابی دسته‌بندی‌شدهٔ معاملات زیان‌ده</h1><p>برندهٔ منتخب High-CAGR، دادهٔ دقیقه‌ای واقعی، همهٔ هزینه‌های بک‌تست. همهٔ زمان‌های این گزارش UTC هستند.</p><p dir="ltr">{html.escape(d['winner_id'])}</p><section><h2>نتیجهٔ اصلی</h2><p>از {r['positions']} پوزیشن پایه، {losers} پوزیشن ({f(losers/r['positions']*100)}٪) زیان‌ده و {r['positions']-losers} سودده بوده‌اند. {r['unit_count']} واحد شامل پایه و افزودن ثبت شده؛ {r['losing_units']} واحد زیان‌ده است. این دو شمارش جایگزین یکدیگر نیستند.</p><p>میانگین برد ${f(r['avg_win'])} و میانگین باخت ${f(r['avg_loss'])} است؛ نسبت اندازهٔ برد به باخت {f(r['avg_win']/-r['avg_loss'])} برابر. باوجود Win Rate={f(r['win_rate_pct'])}٪، سود خالص ${f(r['net_pnl'])} بوده است.</p><p>بزرگ‌ترین دستهٔ شکست، {labels[largest[0]]} است: {largest[1]['positions']} باخت و ${f(-largest[1]['negative_pnl'])} زیان. مشکل غالب باخت‌ها، حرکت نامطلوب قیمت است؛ تنها {cost_flip['positions']} پوزیشن با حرکت خالص قیمت مثبت، صرفاً پس از هزینه‌ها منفی شده‌اند.</p>{periods}</section><section><h2>دسته‌بندی علت‌های مکانیکیِ قابل مشاهده</h2>{categories}<p>دسته‌ها انحصاری و با این تقدم هستند: وارونگی پس از هزینه؛ MFE&lt;0.5R؛ سپس مدت ≤۸ ساعت و MFE&lt;1R؛ سپس MFE≥1R؛ باقی‌مانده. بنابراین ردیف «برگشت سریع» فقط زیرمجموعهٔ 0.5–1R را نشان می‌دهد؛ همهٔ باخت‌های زودهنگام را نه.</p><p>برچسب‌های مستقل و هم‌پوشان: {r['overlapping_tags']['losses_exit_within_8h']} باخت طی ≤۸ ساعت؛ {r['overlapping_tags']['losses_mfe_at_least_1r']} باخت پس از لمس ≥۱R؛ {r['overlapping_tags']['losses_mfe_at_least_2r']} باخت پس از لمس ≥۲R. این تعدادها نباید با دسته‌های جدول جمع شوند.</p><p>{r['cohorts']['exit_kind']['INITIAL_STOP_OR_GAP']['positions']} پوزیشن روی استاپ اولیه یا بدتر از آن بسته شده‌اند؛ {r['cohorts']['exit_kind']['RATCHETED_STOP']['losses']} باخت پس از بالاتر رفتن استاپ در خرید / پایین‌تر رفتن آن در فروش رخ داده‌اند. وجود تریل به‌تنهایی تضمین نمی‌کند استاپ از قیمت ورود عبور کرده باشد.</p></section><section><h2>اثر هزینه‌ها</h2>{table(['مؤلفه','اثر $'],[['PnL حرکت قیمت پیش از لغزش/کارمزد/Funding',f(before)],['لغزش ورود و خروج',f(-r['slippage_drag'])],['کارمزد',f(-r['fees'])],['Funding خالص',f(r['funding_pnl'])],['سود خالص نهایی',f(r['net_pnl'])]])}<p>لغزش از قبل در gross دفتر معاملات لحاظ شده است؛ این جدول آن را فقط برای تفکیک حسابداری باز می‌کند و دوباره از سود خالص کسر نمی‌کند. مجموع اثر منفی هزینه‌ها ${f(costs)} است. تعداد {cost_flip['positions']} وارونگی هزینه‌ای فقط تعداد پوزیشن‌هایی است که علامت سودشان تغییر کرده، نه تمام اثر هزینه بر استراتژی.</p></section><section><h2>افزودن به برنده؛ «واحد جدید» ریسک خودش را دارد</h2><p>{pyr['add_units']} واحد افزوده، {pyr['negative_add_units']} واحد زیان‌ده و ${f(pyr['add_net_pnl'])} سود خالص در مجموع. در {pyr['negative_add_but_combined_positive']} مورد، واحد افزوده زیان داده ولی پوزیشن تجمیعی سودده بوده است. فقط {pyr['negative_combined_positions_with_add']} پوزیشن دارای افزودن در مجموع منفی شده‌اند.</p><p>در آن چهار مورد، خود پایه سودده بود ولی زیان واحد جدید از سود قفل‌شدهٔ پایه بزرگ‌تر شد. «ریسک پایه صفر» به معنای «ریسک کل پوزیشن صفر» نیست.</p><p>آزمون جفت همسان بدون افزودن، CAGR={f(base['full']['cagr_pct'])}٪ و آزمون با افزودن CAGR={f(w['full']['cagr_pct'])}٪ دارد. اختلاف {f(w['full']['cagr_pct']-base['full']['cagr_pct'])} واحد درصد است. اختلاف سود دو اجرا دقیقاً برابر سود مستقیم واحدهای افزوده نیست؛ equity و حجم معاملات بعدی نیز تغییر می‌کنند.</p></section><section><h2>کجا آسیب بیشتر بوده است؟</h2>{cohorts}<p>BTC در کل مثبت بوده ولی مشارکت سود آن کم و در معاملات بسته‌شدهٔ سال ۲۰۲۵ منفی بوده است. این مشاهده به‌تنهایی مجوز حذف BTC نیست؛ حذف نماد، اسلات‌ها و مسیر equity را تغییر می‌دهد و به بک‌تست جدید نیاز دارد.</p><p>Long سهم عمدهٔ سود کل را ساخته است. Short در Train زیان‌ده، ولی در اعتبارسنجی ۲۰۲۵–۲۰۲۶ سودده بوده؛ بنابراین حذف کامل Short از روی مجموع پنج سال نتیجهٔ اثبات‌شده‌ای نیست.</p></section><section><h2>ریسک تجمعی و توالی باخت‌ها</h2>{streaks}{clusters}<p>توالی‌ها بر اساس زمان خروج پوزیشن‌ها هستند؛ معاملات هم‌پوشان و نمادهای مختلف در آن‌ها حضور دارند. ۲۷ باخت متوالی به معنی ۲۷ کندل متوالی نیست.</p><p>زیان هم‌زمان چند نماد نشان می‌دهد تعداد اسلات با تنوع ریسک یکسان نیست. محدودکنندهٔ زیان روزانه ورودهای بعدی را متوقف می‌کند؛ استاپ معاملات از قبل باز را حذف نمی‌کند.</p><p>در موتور فعلی بک‌تست، شمارندهٔ توقف روزانه از PnL خروج پس از کارمزد ساخته می‌شود. Funding جداگانه به balance و سود خالص کل اعمال می‌شود و در شمارندهٔ این توقف نیست؛ اثر تغییر این رفتار هنوز بک‌تست نشده است.</p><p>پنجرهٔ افت در منحنی ساعتی: {dd['start_utc']} تا {dd['end_utc']}، DD نمونه‌برداری‌شده {f(dd['hourly_sampled_dd_pct'])}٪. DD موتور دقیقه‌ای {f(dd['minute_engine_dd_pct'])}٪ است. این دو با رزولوشن متفاوت‌اند و پنجرهٔ ساعتی را نباید زمان دقیق DD دقیقه‌ای معرفی کرد.</p><p>در این پنجره، {dd['closed_position_summary']['positions']} پوزیشن بسته شده، {dd['closed_position_summary']['losses']} مورد زیان‌ده و جمع PnL پوزیشن‌های بسته‌شده ${f(dd['closed_position_summary']['net_pnl'])} است؛ این عدد معادل انتساب کامل DD نیست، چون equity شامل سود/زیان باز و زمان‌بندی Funding نیز هست.</p></section><section><h2>آیا ADX یا شیب کیجون، علت شکست را توضیح می‌دهد؟</h2>{filters}<p>پوزیشن‌های ADX&lt;20 در مجموع ${f(r['cohorts']['adx_cohort']['<20']['net_pnl'])} سود ساخته‌اند. گروه کیجون تخت/خلاف جهت نیز ${f(r['cohorts']['slope_cohort']['flat_or_adverse']['net_pnl'])} سود ساخته است. پس افزودن خودکار ADX≥25 یا حذف همهٔ کیجون‌های تخت از این جدول توجیه نمی‌شود.</p><p>گروه شکست 0.5–1% در این نمونه منفی بوده، اما رابطه یکنواخت نیست: شکست‌های کوچک‌تر از 0.25% سودده بوده‌اند. این‌ها گروه‌بندی توصیفی پس از مشاهده‌اند، نه اثر علّی یا آزمون اثبات‌شدهٔ یک فیلتر تازه.</p></section><section><h2>اولویت آزمون اصلاحی بعدی</h2><ol><li>کنترل ریسک هم‌جهت و هم‌زمانِ پرتفوی؛ آزمون سقف ریسک باز تجمعی یا تعداد کمتر ورود هم‌جهت، با سنجش فرصت‌های از دست‌رفته.</li><li>آزمون تأیید شکست/بازآزمایی برای دستهٔ بدون ادامه؛ بدون بازگرداندن زنجیرهٔ فیلترهای متناقض و بدون فرض سودده بودن فیلتر ADX.</li><li>آزمون محافظت دیرهنگام پس از ۲R برای {r['overlapping_tags']['losses_mfe_at_least_2r']} باخت دارای فرصت ≥۲R؛ با مقایسهٔ اثر آن بر برندگان بزرگ، نه فرض اینکه سربه‌سر حتماً سود را زیاد می‌کند.</li><li>آزمون واحد افزودهٔ کوچک‌تر یا فاصلهٔ بیشتر تا استاپ، با توجه به سود مثبت کل افزودن و ۱۱۳ موردی که فقط واحد اضافه باخته است.</li></ol><p>در این کار هیچ تنظیم استراتژی یا ریسک تغییر نکرده و بک‌تست اصلاحات پیشنهادی اجرا نشده است.</p></section><section><h2>نمونه‌های زیان بزرگ برای بازبینی</h2>{worst}</section><section class="note"><h2>روش و فایل‌ها</h2><p>MFE بیشترین حرکت مثبت نسبت به R پایه و MAE بیشترین حرکت نامطلوب است. دقیقهٔ ورود و خروج به‌دلیل نامعلوم بودن ترتیب tick حذف شده‌اند؛ قیمت‌های fill و دقیقه‌های کامل میانی استفاده شده‌اند. کران بالای MFE با تمام دقیقه‌های مرزی نیز محاسبه شد؛ دستهٔ هیچ‌یک از {losers} باخت با این حساسیت تغییر نکرد.</p><p>ADX هر ورود از ۱۹۹ کندل بسته با همان Wilder(14) بازسازی شده؛ دسته‌های زمان خروج، ریشه/واحد افزوده و هزینه‌ها با دفتر معاملات تطبیق دارند. Full و Train/OOS سرمایهٔ مستقل دارند و جمع‌پذیر نیستند.</p><p>دامنه فقط برندهٔ منتخب است، نه تمام ۳۸۴ تنظیم ردشده. رد سیگنال، باخت نیست: {r['rejections']['min_stop_rejections']} رد فاصلهٔ استاپ، {r['rejections']['slot_rejections']} رد ظرفیت اسلات و {r['rejections']['margin_rejections']} رد مارجین ثبت شده‌اند. علت فردی هر رد در موتور قبلی ذخیره نشده و از این شمارنده‌ها قابل بازسازی دقیق نیست.</p><p>نتایج مربوط به بک‌تست‌اند، نه سفارش واقعی LBank. این تحلیل پس از انتخاب برنده و مشاهدهٔ ۲۰۲۵–۲۰۲۶ انجام شده و آزمون مستقل آینده محسوب نمی‌شود.</p><p><a href="failure_positions_full.csv">CSV همهٔ پوزیشن‌های Full</a> · <a href="failure_units_full.csv">CSV همهٔ واحدهای Full</a> · <a href="failure_diagnostics.json">جزئیات JSON و سه دوره</a></p></section></html>'''
 (OUT/'report_failures_fa.html').write_text(s);print('REPORT',OUT/'report_failures_fa.html')
if __name__=='__main__':main()
